# Exact normalized title keys, including punctuation, spacing, and parenthetical-edition variants.
def title_exact(r):
    import re
    import unicodedata
    import hashlib

    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        return " ".join(s.split())

    def key(tag, value):
        return tag + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    raw = r.get("title", "")
    values = [norm(raw), norm(re.sub(r"\([^)]*\)|\[[^\]]*\]", " ", raw))]
    values += [v.replace(" ", "") for v in values]
    return list(dict.fromkeys(key("t:", v) for v in values if v))


# Exact normalized release keys, with additional keys for compound release components.
def release_exact_and_parts(r):
    import re
    import unicodedata
    import hashlib

    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        return " ".join(s.split())

    def key(value):
        return "r:" + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    raw = r.get("release", "")
    parts = [raw] + re.split(r"\s*(?:/|;|\+|\||\s+-\s+)\s*", raw)
    values = []
    for part in parts:
        value = norm(part)
        if value:
            values.extend((value, value.replace(" ", "")))
    return list(dict.fromkeys(key(v) for v in values if len(v) >= 3))


# Artist alias keys tolerate accents, articles, collaborator lists, credits, and ensemble suffixes.
def artist_aliases_and_components(r):
    import re
    import unicodedata
    import hashlib

    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).casefold()
        s = "".join(c for c in s if not unicodedata.combining(c))
        s = re.sub(r"[^a-z0-9]+", " ", s)
        return " ".join(s.split())

    def variants(value):
        out = {value}
        if value.startswith("the "):
            out.add(value[4:])
        suffixes = (
            " band", " orchestra", " project", " group", " ensemble", " trio",
            " quartet", " quintet", " sextet", " choir", " calypsos"
        )
        for suffix in suffixes:
            if value.endswith(suffix) and len(value) > len(suffix):
                out.add(value[:-len(suffix)].strip())
        return out

    def key(value):
        return "a:" + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    raw = r.get("artist_name", "")
    pieces = [raw]
    pieces += re.split(
        r"\s*(?:;|/|\+|&|_|\s+-\s+|\bfeat(?:uring)?\.?\b|\bwith\b|"
        r"\band\s+(?:his|her|their)\b)\s*",
        raw,
        flags=re.I,
    )
    values = set()
    for piece in pieces:
        value = norm(piece)
        if not value:
            continue
        for alias in variants(value):
            values.add(alias)
            values.add(alias.replace(" ", ""))
    return [key(v) for v in sorted(values) if len(v) >= 3]


# Character-position anchors catch local spelling errors, insertions, and appended title qualifiers.
def title_character_anchors(r):
    import re
    import unicodedata
    import hashlib

    raw = unicodedata.normalize("NFKD", str(r.get("title", "") or "")).casefold()
    raw = "".join(c for c in raw if not unicodedata.combining(c))
    compact = re.sub(r"[^a-z0-9]+", "", raw)
    if len(compact) < 8:
        return []

    width = min(12, max(8, len(compact) // 3))
    starts = (0, max(0, (len(compact) - width) // 2), max(0, len(compact) - width))
    anchors = [compact[i:i + width] for i in starts]
    return list(dict.fromkeys(
        "c:" + hashlib.blake2s(a.encode("utf-8"), digest_size=8).hexdigest()
        for a in anchors if len(a) >= 8
    ))


SCHEMES = {
    "title_exact": title_exact,
    "release_exact_and_parts": release_exact_and_parts,
    "artist_aliases_and_components": artist_aliases_and_components,
    "title_character_anchors": title_character_anchors,
}
